1	@import "tailwindcss";
2	@import "tw-animate-css";
3	@import "shadcn/tailwind.css";
4	
5	@custom-variant dark (&:is(.dark *));
6	
7	@theme inline {
8	  /* ──────────────────────────────────────────────────────────
9	     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
10	     Bone · Onyx · Stone · Rust — no additions, no substitutes
11	  ────────────────────────────────────────────────────────── */
12	  --color-bone: #F7F7F5;
13	  --color-onyx: #0F0F0F;
14	  --color-stone: #787774;
15	  --color-rust: #B23A2B;
16	
17	  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
18	  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
19	  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;
20	
21	  /* ──────────────────────────────────────────────────────────
22	     SEMANTIC PALETTE — derived from brand swatches
23	     Rule: never pure #FFF or #000. Bone/Onyx only.
24	  ────────────────────────────────────────────────────────── */
25	
26	  /* Bone — 60% usage. Page canvas + sidebar bg. */
27	  --color-background: #F7F7F5;
28	
29	  /* Onyx — 20% usage. Primary text + CTAs. */
30	  --color-foreground: #0F0F0F;
31	
32	  /* Card surface — pure white on Bone, so cards "float" */
33	  --color-card: #FFFFFF;
34	  --color-card-foreground: #0F0F0F;
35	
36	  --color-popover: #FFFFFF;
37	  --color-popover-foreground: #0F0F0F;
38	
39	  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
40	  --color-primary: #0F0F0F;
41	  --color-primary-foreground: #F7F7F5;
42	
43	  /* Secondary — muted Bone tint */
44	  --color-secondary: oklch(96% 0.003 60);
45	  --color-secondary-foreground: #0F0F0F;
46	
47	  /* Muted — Stone-tinted backgrounds */
48	  --color-muted: oklch(95% 0.003 60);
49	  --color-muted-foreground: #787774;
50	
51	  /* Accent — Rust at 12% opacity for active nav states */
52	  --color-accent: rgba(178, 58, 43, 0.08);
53	  --color-accent-foreground: #B23A2B;
54	
55	  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
56	  --color-destructive: #B23A2B;
57	  --color-destructive-foreground: #F7F7F5;
58	
59	  /* ──────────────────────────────────────────────────────────
60	     SEMANTIC STATUS TOKENS
61	  ────────────────────────────────────────────────────────── */
62	  --color-success:            oklch(58% 0.18 145);
63	  --color-success-bg:         oklch(94% 0.05 145);
64	  --color-success-foreground: oklch(26% 0.12 145);
65	  --color-warning:            oklch(70% 0.16 72);
66	  --color-warning-bg:         oklch(94% 0.07 72);
67	  --color-warning-foreground: oklch(36% 0.15 72);
68	
69	  /* Borders — Stone-tinted, warm hue, tuned to be visible on bone canvas */
70	  --color-border: oklch(91% 0.005 85);
71	  --color-input: oklch(91% 0.005 85);
72	  --color-ring: #0F0F0F;
73	
74	  /* ──────────────────────────────────────────────────────────
75	     SHADOWS — custom (never use Tailwind default shadow-sm/md)
76	  ────────────────────────────────────────────────────────── */
77	
78	  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
79	  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);
80	
81	  /* Standard card elevation — visible on off-white page */
82	  --shadow-card: 0 1px 3px 0 oklch(20% 0.02 85 / 0.10), 0 2px 4px -1px oklch(20% 0.02 85 / 0.06);
83	
84	  /* Hover elevation */
85	  --shadow-card-hover: 0 6px 16px -4px oklch(20% 0.02 85 / 0.14), 0 3px 8px -2px oklch(20% 0.02 85 / 0.09);
86	
87	  /* Medium depth for drawers, modals */
88	  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);
89	
90	  /* Floating elements — command palette, toasts, tooltips */
91	  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
92	                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);
93	
94	  /* Full-screen overlays — modal backdrop shadow on dialog */
95	  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
96	                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);
97	
98	  /* ──────────────────────────────────────────────────────────
99	     RADIUS
100	  ────────────────────────────────────────────────────────── */
101	  --radius: 0.5rem;
102	  --radius-sm: 0.25rem;
103	  --radius-md: 0.5rem;
104	  --radius-lg: 0.75rem;
105	  --radius-xl: 1rem;
106	  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
107	  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */
108	
109	  /* ──────────────────────────────────────────────────────────
110	     TYPOGRAPHY
111	  ────────────────────────────────────────────────────────── */
112	  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
113	  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;
114	
115	  /* ──────────────────────────────────────────────────────────
116	     TYPOGRAPHY SCALE — semantic names
117	  ────────────────────────────────────────────────────────── */
118	  --text-display-size:    2.25rem;  /* 36px */
119	  --text-display-height:  2.5rem;   /* 40px */
120	  --text-display-weight:  700;
121	  --text-display-track:   -0.02em;
122	
123	  --text-h1-size:    1.75rem;       /* 28px */
124	  --text-h1-height:  2rem;          /* 32px */
125	  --text-h1-weight:  700;
126	  --text-h1-track:   -0.015em;
127	
128	  --text-h2-size:    1.25rem;       /* 20px */
129	  --text-h2-height:  1.75rem;       /* 28px */
130	  --text-h2-weight:  600;
131	  --text-h2-track:   -0.01em;
132	
133	  --text-h3-size:    1rem;          /* 16px */
134	  --text-h3-height:  1.5rem;        /* 24px */
135	  --text-h3-weight:  600;
136	  --text-h3-track:   -0.005em;
137	
138	  --text-body-size:    0.875rem;    /* 14px */
139	  --text-body-height:  1.25rem;     /* 20px */
140	  --text-body-weight:  400;
141	  --text-body-track:   0em;
142	
143	  --text-body-sm-size:    0.8125rem; /* 13px */
144	  --text-body-sm-height:  1.125rem;  /* 18px */
145	  --text-body-sm-weight:  400;
146	  --text-body-sm-track:   0em;
147	
148	  --text-caption-size:    0.75rem;  /* 12px */
149	  --text-caption-height:  1rem;     /* 16px */
150	  --text-caption-weight:  400;
151	  --text-caption-track:   0em;
152	
153	  --text-micro-size:    0.625rem;   /* 10px */
154	  --text-micro-height:  0.875rem;   /* 14px */
155	  --text-micro-weight:  500;
156	  --text-micro-track:   0.06em;     /* uppercase tracking */
157	
158	  /* ──────────────────────────────────────────────────────────
159	     SPACING CONSTANTS — semantic aliases
160	  ────────────────────────────────────────────────────────── */
161	  --spacing-page-x:      1.5rem;   /* px-6 — desktop page horizontal padding */
162	  --spacing-page-x-sm:   1rem;     /* px-4 — mobile page horizontal padding */
163	  --spacing-page-y:      1.5rem;   /* py-6 — vertical section gap */
164	  --spacing-card-pad:    1.5rem;   /* p-6  — card internal padding */
165	  --spacing-card-gap:    1rem;     /* gap-4 — gap between cards in a grid */
166	  --spacing-section-gap: 1.5rem;   /* space-y-6 — between page sections */
167	  --spacing-field-gap:   1rem;     /* space-y-4 — between form fields */
168	
169	  /* ──────────────────────────────────────────────────────────
170	     ICON SIZE SCALE — reference constants (see lib/design-tokens.ts)
171	  ────────────────────────────────────────────────────────── */
172	  --icon-xs:  0.75rem;   /* 12px */
173	  --icon-sm:  0.875rem;  /* 14px */
174	  --icon-md:  1rem;      /* 16px */
175	  --icon-lg:  1.25rem;   /* 20px */
176	  --icon-xl:  1.5rem;    /* 24px */
177	  --icon-2xl: 2rem;      /* 32px */
178	
179	  /* ──────────────────────────────────────────────────────────
180	     SIDEBAR TOKENS (shadcn sidebar primitives)
181	  ────────────────────────────────────────────────────────── */
182	  /* L0 — recessed chrome: ~2% deeper than L1 bone canvas so the sidebar reads
183	     as "behind" the content area. Premium SaaS elevation ladder. */
184	  --sidebar: oklch(95.5% 0.004 85);
185	  --sidebar-background: oklch(95.5% 0.004 85);
186	  --sidebar-foreground: #0F0F0F;
187	  --sidebar-primary: #0F0F0F;
188	  --sidebar-primary-foreground: #F7F7F5;
189	  --sidebar-accent: rgba(178, 58, 43, 0.10);
190	  --sidebar-accent-foreground: #B23A2B;
191	  --sidebar-border: oklch(91% 0.005 85);
192	  --sidebar-ring: #0F0F0F;
193	  --sidebar-width: 15rem;
194	  --sidebar-width-mobile: 18rem;
195	  --sidebar-width-icon: 3.5rem;
196	
197	  /* shadcn token aliases */
198	  --color-sidebar: var(--sidebar);
199	  --color-sidebar-foreground: var(--sidebar-foreground);
200	  --color-sidebar-primary: var(--sidebar-primary);
201	  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
202	  --color-sidebar-accent: var(--sidebar-accent);
203	  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
204	  --color-sidebar-border: var(--sidebar-border);
205	  --color-sidebar-ring: var(--sidebar-ring);
206	
207	  /* ──────────────────────────────────────────────────────────
208	     PAGE LAYOUT — light mode
209	     Brand Book v1.0 — Bone/Stone/Onyx. Hue 85 = warm stone neutral.
210	     (was hue 264 = cool blue — fixed to remove subtle blue tint.)
211	  ────────────────────────────────────────────────────────── */
212	  --color-page-bg: oklch(97.5% 0.003 85);
213	  --color-header-bg: oklch(100% 0 0);
214	  --color-surface-1: oklch(100% 0 0);
215	  --color-surface-2: oklch(97.5% 0.003 85);
216	
217	  /* ──────────────────────────────────────────────────────────
218	     STATUS BADGES — tattoo booking lifecycle
219	  ────────────────────────────────────────────────────────── */
220	  --color-status-pending: oklch(70% 0.16 72);
221	  --color-status-confirmed: oklch(62% 0.24 292);
222	  --color-status-in-progress: oklch(60% 0.2 200);
223	  --color-status-completed: oklch(58% 0.18 145);
224	  --color-status-cancelled: oklch(55% 0.02 85);
225	  --color-status-no-show: oklch(55% 0.22 27);
226	
227	  /* ──────────────────────────────────────────────────────────
228	     NEON ACCENT
229	  ────────────────────────────────────────────────────────── */
230	  --color-neon-purple: oklch(72% 0.28 292);
231	  --color-neon-purple-glow: 0 0 20px oklch(72% 0.28 292 / 0.4);
232	
233	  /* ──────────────────────────────────────────────────────────
234	     CONSENT — submission status colors (Sprint 5)
235	  ────────────────────────────────────────────────────────── */
236	  --color-consent-signed:       oklch(58% 0.18 145);
237	  --color-consent-pending:      oklch(70% 0.16 72);
238	  --color-consent-expired:      oklch(55% 0.02 85);
239	  --color-consent-deleted:      oklch(45% 0.02 85);
240	  --color-consent-opened:       oklch(60% 0.22 230);
241	
242	  /* ──────────────────────────────────────────────────────────
243	     CONSENT — template kind badge colors
244	  ────────────────────────────────────────────────────────── */
245	  --color-kind-tattoo:   oklch(62% 0.24 292);
246	  --color-kind-piercing: oklch(60% 0.22 230);
247	  --color-kind-pmu:      oklch(60% 0.24 340);
248	  --color-kind-touchup:  oklch(70% 0.16 72);
249	  --color-kind-minor:    oklch(55% 0.22 27);
250	
251	  /* ──────────────────────────────────────────────────────────
252	     CONSENT — signature pad
253	  ────────────────────────────────────────────────────────── */
254	  --color-sig-bg:              oklch(6% 0.01 85);
255	  --color-sig-stroke:          oklch(97% 0.01 85);
256	  --color-sig-border:          oklch(28% 0.04 292);
257	  --color-sig-border-active:   oklch(62% 0.24 292 / 0.6);
258	
259	  /* ──────────────────────────────────────────────────────────
260	     CONSENT — public signing page
261	  ────────────────────────────────────────────────────────── */
262	  --color-signing-bg:              oklch(8% 0.01 85);
263	  --color-signing-card:            oklch(12% 0.02 85);
264	  --color-signing-progress-track:  oklch(20% 0.02 85);
265	  --color-signing-progress-fill:   var(--studio-brand-color, oklch(62% 0.24 292));
266	
267	  /* ──────────────────────────────────────────────────────────
268	     CONSENT — template builder
269	  ────────────────────────────────────────────────────────── */
270	  --color-builder-panel-bg:       oklch(10% 0.015 85);
271	  --color-builder-section-bg:     oklch(14% 0.02 85);
272	  --color-builder-section-hover:  oklch(17% 0.025 85);
273	  --color-builder-section-drag:   oklch(12% 0.015 85 / 0.8);
274	  --color-builder-palette-item:   oklch(16% 0.02 85);
275	
276	  /* ──────────────────────────────────────────────────────────
277	     CONSENT — REACH disclosure
278	  ────────────────────────────────────────────────────────── */
279	  --color-reach-bg:     oklch(12% 0.03 292 / 0.4);
280	  --color-reach-border: oklch(62% 0.24 292 / 0.2);
281	
282	  /* ──────────────────────────────────────────────────────────
283	     RETENTION COUNTDOWN
284	  ────────────────────────────────────────────────────────── */
285	  --color-retention-safe: oklch(55% 0.02 85);
286	  --color-retention-warn: oklch(70% 0.16 72);
287	  --color-retention-crit: oklch(55% 0.22 27);
288	
289	  /* ──────────────────────────────────────────────────────────
290	     ANIMATIONS
291	  ────────────────────────────────────────────────────────── */
292	  --animate-fade-in-up: fade-in-up 0.35s ease-out;
293	  --animate-fade-in: fade-in 0.2s ease-out;
294	  --animate-slide-in-right: slide-in-right 0.25s ease-out;
295	
296	  @keyframes fade-in-up {
297	    from { opacity: 0; transform: translateY(6px); }
298	    to   { opacity: 1; transform: translateY(0); }
299	  }
300	  @keyframes fade-in {
301	    from { opacity: 0; }
302	    to   { opacity: 1; }
303	  }
304	  @keyframes slide-in-right {
305	    from { opacity: 0; transform: translateX(8px); }
306	    to   { opacity: 1; transform: translateX(0); }
307	  }
308	
309	  /* ──────────────────────────────────────────────────────────
310	     ONBOARDING PROGRESS
311	  ────────────────────────────────────────────────────────── */
312	  --color-onboarding-track: oklch(22% 0.02 85);
313	  --color-onboarding-fill: oklch(62% 0.24 292);
314	
315	  /* ──────────────────────────────────────────────────────────
316	     CALENDAR — artist color palette (10 artists max per view)
317	  ────────────────────────────────────────────────────────── */
318	  --color-artist-1: oklch(62% 0.24 292);
319	  --color-artist-2: oklch(60% 0.22 230);
320	  --color-artist-3: oklch(58% 0.2 160);
321	  --color-artist-4: oklch(62% 0.22 40);
322	  --color-artist-5: oklch(60% 0.24 340);
323	  --color-artist-6: oklch(58% 0.2 200);
324	  --color-artist-7: oklch(60% 0.18 20);
325	  --color-artist-8: oklch(62% 0.16 280);
326	  --color-artist-9: oklch(58% 0.18 100);
327	  --color-artist-10: oklch(60% 0.2 260);
328	
329	  --color-artist-1-surface: oklch(62% 0.24 292 / 0.12);
330	  --color-artist-2-surface: oklch(60% 0.22 230 / 0.12);
331	  --color-artist-3-surface: oklch(58% 0.2 160 / 0.12);
332	  --color-artist-4-surface: oklch(62% 0.22 40 / 0.12);
333	  --color-artist-5-surface: oklch(60% 0.24 340 / 0.12);
334	  --color-artist-6-surface: oklch(58% 0.2 200 / 0.12);
335	  --color-artist-7-surface: oklch(60% 0.18 20 / 0.12);
336	  --color-artist-8-surface: oklch(62% 0.16 280 / 0.12);
337	  --color-artist-9-surface: oklch(58% 0.18 100 / 0.12);
338	  --color-artist-10-surface: oklch(60% 0.2 260 / 0.12);
339	
340	  /* ──────────────────────────────────────────────────────────
341	     CALENDAR — structural
342	  ────────────────────────────────────────────────────────── */
343	  --calendar-slot-height: 2rem;
344	  --calendar-event-border-radius: 0.375rem;
345	
346	  /* ──────────────────────────────────────────────────────────
347	     BOOKING FLOW (public pages)
348	  ────────────────────────────────────────────────────────── */
349	  --booking-max-w: 44rem;
350	  --color-booking-step-active: oklch(62% 0.24 292);
351	  --color-booking-step-done: oklch(58% 0.18 145);
352	  --color-booking-step-future: oklch(25% 0.02 85);
353	
354	  /* ──────────────────────────────────────────────────────────
355	     APPOINTMENT DETAIL
356	  ────────────────────────────────────────────────────────── */
357	  --color-timeline-line: oklch(22% 0.02 85);
358	  --color-timeline-dot-active: oklch(62% 0.24 292);
359	  --color-timeline-dot-done: oklch(58% 0.18 145);
360	  --color-timeline-dot-future: oklch(25% 0.02 85);
361	
362	  /* ──────────────────────────────────────────────────────────
363	     DRAWER
364	  ────────────────────────────────────────────────────────── */
365	  --animate-sheet-in: sheet-slide-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
366	  @keyframes sheet-slide-in {
367	    from { transform: translateX(100%); opacity: 0; }
368	    to   { transform: translateX(0); opacity: 1; }
369	  }
370	
371	  /* ──────────────────────────────────────────────────────────
372	     CLIENT CRM TAGS — system + user-defined colors
373	  ────────────────────────────────────────────────────────── */
374	  --color-tag-purple:  oklch(62% 0.24 292);
375	  --color-tag-blue:    oklch(60% 0.22 230);
376	  --color-tag-emerald: oklch(58% 0.18 145);
377	  --color-tag-amber:   oklch(70% 0.16 72);
378	  --color-tag-red:     oklch(55% 0.22 27);
379	  --color-tag-pink:    oklch(60% 0.24 340);
380	  --color-tag-cyan:    oklch(58% 0.2 200);
381	  --color-tag-gray:    oklch(55% 0.02 85);
382	
383	  /* ──────────────────────────────────────────────────────────
384	     CLIENT HERO GRADIENT (avatar + stats strip bg)
385	  ────────────────────────────────────────────────────────── */
386	  --color-hero-gradient-from: oklch(62% 0.24 292);
387	  --color-hero-gradient-to:   oklch(60% 0.22 230);
388	
389	  /* ──────────────────────────────────────────────────────────
390	     INACTIVE / ARCHIVE STATES
391	  ────────────────────────────────────────────────────────── */
392	  --color-inactive-overlay: oklch(9% 0.015 85 / 0.5);
393	  --color-archive-bg:       oklch(14% 0.02 85);
394	  --color-archive-border:   oklch(20% 0.02 85);
395	
396	  /* ──────────────────────────────────────────────────────────
397	     COMMUNICATIONS LOG
398	  ────────────────────────────────────────────────────────── */
399	  --color-comm-sms:       oklch(62% 0.22 230);
400	  --color-comm-email:     oklch(62% 0.24 292);
401	  --color-comm-whatsapp:  oklch(58% 0.18 145);
402	  --color-comm-delivered: oklch(58% 0.18 145);
403	  --color-comm-failed:    oklch(55% 0.22 27);
404	  --color-comm-queued:    oklch(70% 0.16 72);
405	
406	  /* ──────────────────────────────────────────────────────────
407	     LIGHTBOX
408	  ────────────────────────────────────────────────────────── */
409	  --color-lightbox-bg: oklch(5% 0.01 85 / 0.95);
410	
411	  /* ──────────────────────────────────────────────────────────
412	     NOTES CATEGORIES
413	  ────────────────────────────────────────────────────────── */
414	  --color-note-general:      oklch(55% 0.02 85);
415	  --color-note-medical:      oklch(55% 0.22 27);
416	  --color-note-allergies:    oklch(62% 0.22 40);
417	  --color-note-skin:         oklch(58% 0.2 200);
418	  --color-note-emergency:    oklch(55% 0.22 27);
419	  --color-note-aftercare:    oklch(58% 0.18 145);
420	  --color-note-preferences:  oklch(62% 0.24 292);
421	  --color-note-artist:       oklch(60% 0.22 230);
422	
423	  /* ──────────────────────────────────────────────────────────
424	     BILLING — subscription status colors
425	  ────────────────────────────────────────────────────────── */
426	  --color-sub-active:    oklch(58% 0.18 145);
427	  --color-sub-trialing:  oklch(62% 0.24 292);
428	  --color-sub-past-due:  oklch(70% 0.16 72);
429	  --color-sub-canceled:  oklch(55% 0.02 85);
430	  --color-sub-unpaid:    oklch(55% 0.22 27);
431	
432	  /* ──────────────────────────────────────────────────────────
433	     BILLING — invoice status colors
434	  ────────────────────────────────────────────────────────── */
435	  --color-inv-paid:            oklch(58% 0.18 145);
436	  --color-inv-open:            oklch(70% 0.16 72);
437	  --color-inv-void:            oklch(55% 0.02 85);
438	  --color-inv-uncollectible:   oklch(55% 0.22 27);
439	  --color-inv-refunded:        oklch(60% 0.22 230);
440	
441	  /* ──────────────────────────────────────────────────────────
442	     BILLING — deposit / payment status
443	  ────────────────────────────────────────────────────────── */
444	  --color-deposit-paid:    oklch(58% 0.18 145);
445	  --color-deposit-pending: oklch(70% 0.16 72);
446	  --color-deposit-failed:  oklch(55% 0.22 27);
447	
448	  /* ──────────────────────────────────────────────────────────
